# ============================================================================
# gen_assets_rc.ps1 - Build the embedded-resource files from the assets dir.
#   outputs:
#     assets\assets.rc        - resource script (numeric ids, RCDATA)
#     src\assets_index.h      - generated filename -> resource id table
# Note: keep this file ASCII-only (PS 5.1 parser).
# ============================================================================
param(
    [string]$AssetsDir = (Join-Path $PSScriptRoot 'assets'),
    [string]$SrcDir    = (Join-Path $PSScriptRoot 'src')
)

$RcFile    = Join-Path $AssetsDir 'assets.rc'
$IndexFile = Join-Path $SrcDir 'assets_index.h'

$files = @(Get-ChildItem -LiteralPath $AssetsDir -File |
           Where-Object { $_.Extension -ne '.rc' } |
           Sort-Object Name)

# ---- assets.rc -------------------------------------------------------------
$sb = New-Object System.Text.StringBuilder
[void]$sb.AppendLine('// auto-generated by gen_assets_rc.ps1 - do not edit')
[void]$sb.AppendLine('#pragma code_page(65001)')
[void]$sb.AppendLine('')
$id = 0
foreach ($f in $files) {
    $id++
    [void]$sb.AppendLine(('{0} RCDATA "{1}"' -f $id, $f.Name))
}
[System.IO.File]::WriteAllText($RcFile, $sb.ToString(), (New-Object System.Text.UTF8Encoding($true)))

# ---- assets_index.h --------------------------------------------------------
$hb = New-Object System.Text.StringBuilder
[void]$hb.AppendLine('// auto-generated by gen_assets_rc.ps1 - do not edit')
[void]$hb.AppendLine('#pragma once')
[void]$hb.AppendLine('')
[void]$hb.AppendLine('// Embedded resource table: file name -> resource id (ids defined in assets.rc)')
[void]$hb.AppendLine('struct EmbeddedAssetEntry {')
[void]$hb.AppendLine('    const char* name;')
[void]$hb.AppendLine('    int         id;')
[void]$hb.AppendLine('};')
[void]$hb.AppendLine('')
[void]$hb.AppendLine(('static const EmbeddedAssetEntry kEmbeddedAssetTable[{0}] = {{' -f $files.Count))
$id = 0
foreach ($f in $files) {
    $id++
    [void]$hb.AppendLine(('    {{ "{0}", {1} }},' -f $f.Name, $id))
}
[void]$hb.AppendLine('};')
[void]$hb.AppendLine('')
[void]$hb.AppendLine(('static const int kEmbeddedAssetCount = {0};' -f $files.Count))
[System.IO.File]::WriteAllText($IndexFile, $hb.ToString(), (New-Object System.Text.UTF8Encoding($true)))

$total = ($files | Measure-Object Length -Sum).Sum
Write-Output ("WROTE {0} and {1} : {2} resources, {3:N1} MB" -f $RcFile, $IndexFile, $files.Count, ($total / 1MB))
